<?php declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';use StudPulse\Database\DB;use StudPulse\Domain\Input;if(PHP_SAPI!=='cli'){exit(1);}$opts=getopt('',['user:','login:','group:','term:','role:','evidence:','valid-until:']);foreach(['group','term','evidence','valid-until']as$k){if(empty($opts[$k])){throw new RuntimeException('Required: --group UUID --term UUID --evidence URL/record --valid-until ISO8601 [--role student|headman|deputy]');}}$role=$opts['role']??'student';if(!in_array($role,['student','headman','deputy'],true)||strlen($opts['evidence'])<10){throw new RuntimeException('Verified evidence and permitted role required');}if(isset($opts['user'])===isset($opts['login'])){throw new RuntimeException('Specify one of --user UUID or --login BARS_LOGIN');}if(isset($opts['login'])){$login=Input::text($opts,'login',100);$accounts=DB::all("SELECT b.user_id FROM bars_accounts b JOIN users u ON u.id=b.user_id AND u.status='active' WHERE b.login=?",[$login]);if(count($accounts)!==1){throw new RuntimeException('Exactly one active account with this BARS login required');}$opts['user']=$accounts[0]['user_id'];}foreach(['user','group','term']as$k){Input::id($opts[$k]);}$until=Input::date($opts['valid-until']);if(strtotime($until.' UTC')<=time()){throw new RuntimeException('Expiry must be in future');}DB::transaction(function()use($opts,$role,$until){$user=DB::one("SELECT id FROM users WHERE id=? AND status='active' FOR UPDATE",[$opts['user']]);if(!$user){throw new RuntimeException('Active user required');}$g=DB::one('SELECT university_id,academic_year FROM academic_groups WHERE id=?',[$opts['group']]);$t=DB::one('SELECT university_id,academic_year FROM terms WHERE id=?',[$opts['term']]);if(!$g||!$t||$g['university_id']!==$t['university_id']||$g['academic_year']!==$t['academic_year']){throw new RuntimeException('Group and term tenant mismatch');}DB::run('UPDATE group_memberships SET valid_to=UTC_TIMESTAMP(6) WHERE user_id=? AND valid_to>UTC_TIMESTAMP(6)',[$opts['user']]);DB::run('INSERT INTO group_memberships(id,group_id,user_id,term_id,role,verified_source,verified_at,valid_from,valid_to) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6),?)',[DB::id(),$opts['group'],$opts['user'],$opts['term'],$role,$opts['evidence'],$until]);DB::run('INSERT INTO audit_events(id,actor_user_id,target_group_id,action,target_type,target_id,result,correlation_id) VALUES(?,NULL,?,?,?,?,?,?)',[DB::id(),$opts['group'],'membership.verified_by_operator','user',$opts['user'],'success',bin2hex(random_bytes(12))]);});echo"Membership verified. No university identity or official write permissions granted.\n";